import java.io.*;
import java.util.*;

public class CF1096G_Variant1 {
    static final int MOD = 998244353;
    static long[] baseW, baseW_;
    static long modPower(int base, int exp) {
        long result = 1;
        long b = base;
        int e = exp;
        while (e > 0) {
            if ((e & 1) == 1)
                result = result * b % MOD;
            b = b * b % MOD;
            e >>= 1;
        }
        return result;
    }
    static void initialize() {
        baseW = new long[21];
        baseW_ = new long[21];
        for (int h = 0; h <= 20; h++) {
            baseW[h] = modPower(3, (MOD - 1) >> h);
            baseW_[h] = modPower(3, (MOD - 1) - ((MOD - 1) >> h));
        }
    }
    static void fft(int[] array, int size, boolean invert) {
        for (int i = 1, j = 0; i < size; i++) {
            int mask = size;
            do
                j ^= mask >>= 1;
            while ((j & mask) == 0);
            if (i < j) {
                int temp = array[i]; array[i] = array[j]; array[j] = temp;
            }
        }
        for (int h = 0, blockSize; (blockSize = 1 << h) < size; h++) {
            long wFactor = invert ? baseW_[h + 1] : baseW[h + 1];
            for (int start = 0; start < size; start += blockSize * 2) {
                long w = 1;
                for (int j = 0; j < blockSize; j++) {
                    int leftIdx = start + j, rightIdx = leftIdx + blockSize;
                    long u = array[leftIdx], v = array[rightIdx] * w;
                    array[leftIdx] = (int)((u + v) % MOD);
                    array[rightIdx] = (int)((u - v + MOD) % MOD);
                    w = w * wFactor % MOD;
                }
            }
        }
    }
    public static void main(String[] args) throws IOException {
        initialize();
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer tokenizer = new StringTokenizer(reader.readLine());
        int nHalf = Integer.parseInt(tokenizer.nextToken()) / 2;
        int kCount = Integer.parseInt(tokenizer.nextToken());
        int sizePower = 1;
        while (sizePower < nHalf * 9 + 1)
            sizePower <<= 1;
        int[] array = new int[sizePower];
        tokenizer = new StringTokenizer(reader.readLine());
        for (int i = 0; i < kCount; i++) {
            int d = Integer.parseInt(tokenizer.nextToken());
            array[d] = 1;
        }
        fft(array, sizePower, false);
        for (int i = 0; i < sizePower; i++)
            array[i] = (int) modPower(array[i], nHalf);
        fft(array, sizePower, true);
        long invSize = modPower(sizePower, MOD - 2);
        long total = 0;
        for (int i = 0; i < sizePower; i++) {
            array[i] = (int) (array[i] * invSize % MOD);
            if (array[i] < 0)
                array[i] += MOD;
        }
        for (int i = 0; i <= nHalf * 9; i++) {
            long val = array[i];
            total = (total + val * val) % MOD;
        }
        System.out.println(total);
    }
}
